changes.before:
.favorite-group-menu-toggle:hover { background: var(--surface-soft); color: var(--accent); }
.favorite-group-edit input { min-width: 0; height: 27px; padding: 0 6px; border: 0; border-bottom: 1px solid var(--accent); outline: 0; background: transparent; color: var(--text); font-size: 12px; }
.favorite-group-edit button { width: 28px; height: 27px; padding: 0; border: 1px solid var(--line); border-radius: 5px; background: var(--surface); color: var(--muted); cursor: pointer; }
/* 字段错误只在需要时占一行，和输入框对齐；不是常驻诊断卡片。 */
.favorite-group-name-error { flex: 0 0 100%; grid-column: 2 / -1; color: var(--danger); font-size: 11px; line-height: 1.4; }
.favorite-group-create input[aria-invalid="true"], .favorite-group-edit input[aria-invalid="true"] { border-color: var(--danger); }
.favorite-group-overlay-layer { position: absolute; inset: 0; z-index: 60; pointer-events: none; }
.favorite-group-overlay-layer > * { pointer-events: auto; }
.favorite-group-overlay { position: absolute; top: 0; right: auto; bottom: auto; }
.favorite-group-menu { width: 112px; display: grid; gap: 2px; padding: 4px; border: 1px solid #e0e0e4; border-radius: 6px; background: var(--surface); box-shadow: 0 7px 18px rgba(34, 35, 40, .12); }
.favorite-group-menu button { height: 26px; padding: 0 7px; border: 0; border-radius: 4px; background: transparent; color: #5f6168; font-size: 12px; text-align: left; cursor: pointer; }

