changes.before:
.favorite-list-heading small { color: var(--browse-quiet); font-size: 11px; font-weight: 400; }
.favorite-export-entry { margin-left: auto; padding: 0 4px; border: 0; background: transparent; color: var(--accent); font-size: 11px; cursor: default; opacity: .58; }
.favorite-conversation-list { min-height: 0; display: grid; align-content: start; gap: 2px; margin-top: 4px; overflow-y: auto; scrollbar-width: thin; }
.favorite-conversation { width: 100%; display: grid; gap: 5px; padding: 9px 8px; border: 0; border-radius: 7px; background: transparent; color: var(--browse-text); text-align: left; cursor: pointer; }
.favorite-conversation:hover, .favorite-conversation:focus-visible { background: var(--surface-soft); }
.favorite-conversation strong { overflow: hidden; color: var(--browse-heading); font-size: 12px; font-weight: 500; line-height: 1.35; text-overflow: ellipsis; white-space: nowrap; }
.favorite-conversation-meta { min-width: 0; display: flex; align-items: center; justify-content: space-between; gap: 8px; color: var(--browse-muted); font-size: 11px; line-height: 1.2; }
.favorite-conversation-meta > span:first-child { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }

