.favorite-conversation-row { min-width: 0; display: grid; grid-template-columns: minmax(0, 1fr) 24px; align-items: start; border-radius: 7px; }
.favorite-conversation-row:hover { background: var(--surface-soft); }
.favorite-entry-menu-toggle { width: 24px; height: 24px; margin-top: 6px; padding: 0; border: 0; border-radius: 5px; background: transparent; color: var(--browse-faint); font-size: 14px; line-height: 1; letter-spacing: 1px; opacity: 0; cursor: pointer; }
.favorite-conversation-row:hover .favorite-entry-menu-toggle, .favorite-conversation-row:focus-within .favorite-entry-menu-toggle, .favorite-entry-menu-toggle[aria-expanded="true"] { opacity: 1; }
.favorite-entry-menu-toggle:hover { background: var(--surface-soft); color: var(--accent); }
.favorite-entry-menu-toggle:focus-visible { outline: 2px solid var(--accent-ring); outline-offset: 2px; }
